import re

from moler.exceptions import CommandFailure
from moler.exceptions import ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand


class AutoStats(GenericEMSSIMCommand):
    """Autostats command class."""

    def __init__(self, connection, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Autostats command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(AutoStats, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                        runner=runner)

        self.options = options
        self.parse_configuration = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "auto_stats"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_status_line(line)
                self._parse_configuration_line(line)
                self._parse_end_line(line)
                self._command_error(line)
            except ParsingDone:
                pass
        return super(AutoStats, self).on_new_line(line, is_full_line)

    _re_status = re.compile(r"Automatic\sPM\sStats\supload\sand\sparse\s(is\s)?(already\s)?(?P<STATUS>\w+)", re.I)

    def _parse_status_line(self, line):
        if self._regex_helper.search_compiled(AutoStats._re_status, line):
            self.current_ret['STATUS'] = self._regex_helper.group('STATUS')
            self.parse_configuration = True
            raise ParsingDone

    _re_configuration_line = re.compile(r"\|(?P<ATTR>.*):\s*(?P<VALUE>.*)", re.I)

    def _parse_configuration_line(self, line):
        if self.parse_configuration and self._regex_helper.search_compiled(AutoStats._re_configuration_line, line):
            self.current_ret[self._regex_helper.group("ATTR")] = self._regex_helper.group("VALUE")
            raise ParsingDone

    _re_next_run = re.compile(r"\|Next\srun\safter\s(?P<NEXT_RUN>.*)\sseconds", re.I)

    def _parse_end_line(self, line):
        if self._regex_helper.search_compiled(AutoStats._re_next_run, line):
            self.current_ret['Next run [s]'] = self._regex_helper.group("NEXT_RUN")
            self.set_result(self.current_ret)
            raise ParsingDone

    _re_error = re.compile(r".*ERROR:(?P<ERROR>.*)", re.I)
    _re_syntax_msg = re.compile(r".*Usage:\sauto_stats.*", re.I)

    def _command_error(self, line):
        """
        Catch errors.

        :param line: Line from device.
        :return: None.
        """
        if self._regex_helper.search_compiled(AutoStats._re_error, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone
        elif self._regex_helper.search_compiled(AutoStats._re_syntax_msg, line):
            self.set_exception(CommandFailure(self, "ERROR: invalid syntax"))
            raise ParsingDone


